<script setup>import{ref,onMounted}from'vue';import api from'../services/api';const programs=ref([]);onMounted(async()=>{try{programs.value=(await api.get('/affiliate-programs')).data.programs||[]}catch{}})</script><template><section><div class="rounded-3xl bg-indigo-600 p-8 text-white"><p class="font-bold uppercase tracking-wider text-indigo-200">Affiliate program</p><h1 class="mt-2 text-4xl font-black">Turn recommendations into earnings.</h1><p class="mt-3 text-indigo-100">Share product links and track performance.</p></div><h2 class="mt-10 text-xl font-black">Available programs</h2><div class="mt-4 grid gap-4 md:grid-cols-2"><div v-for="p in programs" :key="p.id" class="rounded-2xl border bg-white p-5"><b>{{p.name}}</b><p class="mt-2 text-slate-500">{{p.commissionType==='percentage'?p.commissionRate+'% commission':'Fixed commission'}}</p></div></div></section></template>